mapper.select:
${pagingTop}
WITH numbered_rows AS ( SELECT member_id, member_name, applicant_cell_phone, TO_CHAR(add_date, 'yyyy-MM-dd HH24:mi') AS formatted_add_date, ROW_NUMBER() OVER (PARTITION BY member_id ORDER BY add_date) AS row_num FROM NEIGHBORHOOD_LIBRARY_RESERVE WHERE cancel_yn != 'Y' AND applicant_cell_phone IS NOT NULL
AND add_date BETWEEN TO_DATE(#{start_date}||' 090000','yyyy-MM-dd HH24miss') AND TO_DATE(#{end_date}||' 090000','yyyy-MM-dd HH24miss')
AND member_id NOT IN ( SELECT distinct member_id FROM NEIGHBORHOOD_LIBRARY_RAFFLE ) ) SELECT member_id, member_name AS name, applicant_cell_phone AS member_phone, formatted_add_date AS add_date FROM numbered_rows WHERE row_num = 1
${pagingBottom}

mapper.insert:

INSERT INTO NEIGHBORHOOD_LIBRARY_RAFFLE_SETTING
	(
		raffle_idx, raffle_name, raffle_count, win_count, add_date
	) VALUES (
		#{raffle_idx}, #{raffle_name}, #{raffle_count}, #{win_count}, SYSDATE
	)
